import { type Claim, isCutShort } from "../domain/verdict.ts";

/** What `mod.ts` read about the file of a claim. `size` is `undefined` when the path is not a file, and `text` is read only for a claim of `cut`. */
export type Disk = {
  readonly exists: boolean;
  readonly size: number | undefined;
  readonly text: string | undefined;
};

/** True when the disk backs `claim`. A file that the check cannot read does not back a claim of `empty` or `cut`. */
export const holds = (
  { state }: Claim,
  { exists, size, text }: Disk,
): boolean => {
  if (state === "missing") return !exists;
  if (size === undefined) return false;
  if (state === "empty") return size === 0;
  return text !== undefined && isCutShort(text);
};
